      speakerName: "收益机遇 Agent",
      timestamp: Date.now() - 240000,
    },
    {
      id: "p-black",
      hat: "black",
      headline: "致命风险在于学习曲线陡峭与商业交付延期，团队可能陷入借用检查黑洞",
